	always @(posedge clock) begin
		if (!reset) begin
			if (wrapper.uut.latched_store && h_is_c_addi4spn) begin
				h_addi4spn_has_rs1_capture: assert(wrapper.uut.dbg_rs1val_valid);
			end
		end
	end

	// Once rs1 has been captured for C.ADDI4SPN, dbg_rs1val and reg_op1 must agree (same operand).
	always @(posedge clock) begin
		if (!reset) begin
			if (h_is_c_addi4spn && wrapper.uut.dbg_rs1val_valid) begin
				h_addi4spn_dbg_rs1val_matches_op1: assert(wrapper.uut.dbg_rs1val == wrapper.uut.reg_op1);
			end
		end
